def compute(vars):
    useful_life = vars["v1"]
    if useful_life == 0:
        return None

    yearly_amortization_rate = 1 / useful_life

    return {
        "value": yearly_amortization_rate,
        "trace": {
            "useful_life_years": useful_life,
            "yearly_amortization_rate": yearly_amortization_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "per year"
            }
        }
    }
